        		List<Individual> unfilteredIndividualList = getIndividualList(
        				theClass);
        		Iterator<Individual> unfilteredIt  = unfilteredIndividualList
        													.iterator();
        		for (Individual filt : graphFilteredIndividualList) {
        			Individual unfilt = unfilteredIt.next();
        			while (!unfilt.getURI().equals(filt.getURI())) {
        				unfilt = unfilteredIt.next();
        			}
        			ents.add(unfilt);
        		}
        	} else {
        		ents = getIndividualList(theClass);
        	}
        }

        java.util.Collections.sort(ents);

        if (quantity > 0 && offset > 0) {
            List<Individual> sublist = new ArrayList<>();
            for (int i = offset - 1; i < ((offset - 1) + quantity); i++) {
                sublist.add(ents.get(i));
            }
            return sublist;
        }

        return ents;

    }

    private List<Individual> getIndividualList(Resource theClass) {
    	final List<Individual> ents = new ArrayList<>();
   	    DatasetWrapper w = getDatasetWrapper();
	    Dataset dataset = w.getDataset();
    	dataset.getLock().enterCriticalSection(Lock.READ);
    	try {
    		String query =
	    		"SELECT DISTINCT ?ind ?label " +
	    		"WHERE " +
	    		 "{ \n" +
                    "{   ?ind a <" + theClass.getURI() + "> } \n" +
	    		 	"UNION { \n" +
                    "    ?ind a <" + theClass.getURI() + "> . \n" +
	    		 	"    ?ind  <" + RDFS.label.getURI() + "> ?label \n" +
	    		 	"} \n" +
	    		 "} ORDER BY ?ind ?label";

            RDFService rdfService = wadf.getRDFService();
            try {
                rdfService.sparqlSelectQuery(
                        query, new ResultSetConsumer() {
                            String uri = null;
                            String label = null;

                            @Override
                            protected void processQuerySolution(QuerySolution qs) {
                                Resource currRes = qs.getResource("ind");
                                if (currRes.isAnon()) {
                                    return;
                                }

                                if (uri != null && !uri.equals(currRes.getURI())) {
                                    try {
                                        ents.add(makeIndividual(uri, label));
                                    } catch (IndividualNotFoundException e) {
                                        // don't add
                                    }
                                    uri = currRes.getURI();
                                    label = null;
                                } else if (uri == null) {
                                    uri = currRes.getURI();
                                }
                                Literal labelLit = qs.getLiteral("label");
                                if (labelLit != null) {
                                    label = labelLit.getLexicalForm();
                                }
                            }

                            @Override
                            protected void endProcessing() {
                                if (uri != null) {
                                    try {
                                        ents.add(makeIndividual(uri, label));
                                    } catch (IndividualNotFoundException e) {
                                        // don't add
                                    }
                                }
                            }
                        });
            } catch (RDFServiceException e) {
                log.debug(e,e);
                throw new RuntimeException(e);
            }
    	} finally {
    		dataset.getLock().leaveCriticalSection();
    		w.close();
    	}
        return ents;
    }

    private List<Individual> getGraphFilteredIndividualList(Resource theClass,
    		                                                String filterStr) {
		final List<Individual> filteredIndividualList = new ArrayList<>();
		DatasetWrapper w = getDatasetWrapper();
   	    Dataset dataset = w.getDataset();
       	dataset.getLock().enterCriticalSection(Lock.READ);
       	try {
    		String query =
    			"SELECT DISTINCT ?ind " +
    			"WHERE " +
    			"{ GRAPH ?g { \n" +
                	"{   ?ind a <" + theClass.getURI() + "> } \n" +
                "  } \n" + filterStr +
                "} ORDER BY ?ind";
    		RDFService rdfService = wadf.getRDFService();
    		try {
    		    rdfService.sparqlSelectQuery(
                        query, new ResultSetConsumer() {
                            @Override
                            protected void processQuerySolution(QuerySolution qs) {
                                Resource currRes = qs.getResource("ind");
                                if (!currRes.isAnon()) {
                                    try {
                                        filteredIndividualList.add(
                                                makeIndividual(currRes.getURI(), null));
                                    } catch (IndividualNotFoundException e) {
                                        // don't add
                                    }
                                }
                            }
                        });
    		} catch (RDFServiceException e) {
    		    log.debug(e,e);
    		    throw new RuntimeException(e);
    		}
       	} finally {
    		dataset.getLock().leaveCriticalSection();
    		w.close();
		}
       	return filteredIndividualList;
    }

    private Individual makeIndividual(String uri, String label) throws IndividualNotFoundException {
        Individual ent = new IndividualSDB(uri,
                this.dwf, datasetMode, wadf,
                SKIP_INITIALIZATION);
        ent.setName(label);
		ent.setRdfsLabel(label);
        return ent;
    }

    @Override
    public Individual getIndividualByURI(String entityURI) {
        if( entityURI == null || entityURI.length() == 0 ) {
            return null;
        } else {
        	return makeIndividual(entityURI);
